use std::io::*;

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    let mut it = s.split_ascii_whitespace();
    let t: usize = it.next().unwrap().parse().unwrap();
    const N: usize = 200001;
    let mut comp = vec![false; N];
    let mut cnt = vec![0usize; N];
    let mut last = vec![0usize; N];
    for i in 2..N {
        if !comp[i] {
            let mut j = i * i;
            while j < N {
                comp[j] = true;
                j += i;
            }
        }
    }
    for i in 0..N {
        let p = i >= 2 && !comp[i];
        cnt[i] = if i > 0 { cnt[i - 1] } else { 0 } + p as usize;
        last[i] = if p { i } else if i > 0 { last[i - 1] } else { 0 };
    }
    let mut o = String::new();
    for _ in 0..t {
        let n: usize = match it.next() {
            Some(x) => x.parse().unwrap(),
            None => break,
        };
        if last[n] == 0 {
            o.push_str("0 none\n");
        } else {
            o.push_str(&format!("{} {}\n", cnt[n], last[n]));
        }
    }
    print!("{}", o);
}

